CREATE ROLE anon;CREATE ROLE authenticated;CREATE ROLE service_role;CREATE SCHEMA auth;
CREATE FUNCTION auth.uid()RETURNS uuid LANGUAGE sql AS $$SELECT NULL::uuid$$;
CREATE TABLE settlement_locks(lock_type text,is_active boolean);
CREATE TABLE union_settlement_floor(union_id uuid,earliest_period_start timestamptz);
CREATE TABLE rakeback_periods(club_id uuid,status text,rakeback_amount numeric,period_start date,period_end date);
CREATE TABLE union_rake_rollup_days(union_id uuid,day date);
CREATE TABLE accounting_cash_rake_sources(club_id uuid,recorded_at timestamptz,earned_at timestamptz);
CREATE TABLE accounting_cash_atomic_contract_admissions(source_id uuid,admitted_at timestamptz);
ALTER TABLE accounting_cash_rake_sources ADD COLUMN id uuid;
CREATE TABLE accounting_tournament_fee_sources(club_id uuid,charged_at timestamptz,recorded_at timestamptz);
CREATE TABLE accounting_period_recompute_requests(id uuid PRIMARY KEY,club_id uuid,period_start date,period_end date,requested_at timestamptz,last_requested_at timestamptz,attempted_at timestamptz,status text,last_result jsonb,UNIQUE(club_id,period_start,period_end));
CREATE TABLE accounting_routed_settlement_runs(union_id uuid,scope_kind text,scope_id uuid,period_start timestamptz,period_end timestamptz,round_no int,result jsonb,PRIMARY KEY(union_id,period_start,period_end,round_no));
CREATE TABLE union_settlement_rounds(union_id uuid,period_start timestamptz,period_end timestamptz,round_no int,round_name text,payers int,payees int,amount numeric,shortfalls int,detail jsonb,PRIMARY KEY(union_id,period_start,period_end,round_no));
CREATE TABLE settlement_invoices(club_id uuid,invoice_type text,breakdown jsonb,message_sent boolean,status text);
CREATE TABLE settlement_periods(union_id uuid,start_at timestamptz,end_at timestamptz,status text);
CREATE TABLE phase_accounts(kind text PRIMARY KEY,balance numeric NOT NULL CHECK(balance>=0));
INSERT INTO phase_accounts VALUES('union_rake',1000),('union_bank',0),('club',100),('agent',0),('player',0);
CREATE TABLE phase_legs(stage int PRIMARY KEY,amount numeric NOT NULL);
CREATE TABLE phase_trace(seq bigint GENERATED ALWAYS AS IDENTITY,event text);
CREATE TABLE phase_round1(result jsonb);
CREATE FUNCTION u()RETURNS uuid LANGUAGE sql IMMUTABLE AS $$SELECT 'fade0000-0000-0000-0000-000000000001'::uuid$$;
CREATE FUNCTION c()RETURNS uuid LANGUAGE sql IMMUTABLE AS $$SELECT 'a0000000-0000-0000-0000-000000000001'::uuid$$;
CREATE FUNCTION fn_caller_is_engine()RETURNS boolean LANGUAGE sql AS $$SELECT coalesce(current_setting('test.engine',true),'true')='true'$$;
CREATE FUNCTION fn_is_union_overseer(uuid,uuid)RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION fn_ca_launch_accounting_waived(text,uuid,timestamptz)RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION fn_union_week_start(timestamptz)RETURNS timestamptz LANGUAGE sql IMMUTABLE AS $$SELECT date_trunc('week',$1 AT TIME ZONE 'America/Los_Angeles') AT TIME ZONE 'America/Los_Angeles'$$;
CREATE FUNCTION fn_union_prev_week_start(timestamptz)RETURNS timestamptz LANGUAGE sql AS $$SELECT fn_union_week_start($1-interval '7 days')$$;
CREATE FUNCTION fn_union_pnl_closed_book_barrier(timestamptz)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF $1>now()THEN RAISE EXCEPTION 'book_not_closed';END IF;END$$;
CREATE FUNCTION fn_accounting_week_clubs(uuid,uuid,timestamptz,timestamptz)RETURNS TABLE(club_id uuid)LANGUAGE sql AS $$SELECT c()$$;
CREATE FUNCTION fn_lock_rakeback_payer_clubs(uuid[])RETURNS void LANGUAGE plpgsql AS $$BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('fixture-original-payer:'||$1::text,0));END$$;
CREATE FUNCTION fn_cash_source_refusals_for_period(uuid,uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO phase_trace(event)VALUES('cash_sources');RETURN CASE WHEN current_setting('test.source_bad',true)='on' THEN '{"status":"blocked","count":1,"sources":["missing"]}'::jsonb ELSE '{"status":"ready","count":0,"sources":[]}'::jsonb END;END$$;
CREATE FUNCTION fn_union_pnl_close_quality(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO phase_trace(event)VALUES('pnl');RETURN CASE current_setting('test.pnl',true)WHEN 'ready'THEN '{"status":"ready","issues":[]}'::jsonb WHEN 'warming'THEN '{"status":"blocked","issues":["union_pnl_certification_in_progress"]}'::jsonb ELSE '{"status":"blocked","issues":["original_book_issue"]}'::jsonb END;END$$;
CREATE FUNCTION fn_rakeback_recompute_split(uuid,date,date)RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE x accounting_period_recompute_requests%ROWTYPE;r jsonb;BEGIN INSERT INTO phase_trace(event)VALUES('recompute');IF current_setting('test.recompute_bad',true)='on'THEN RETURN '{"status":"in_progress"}'::jsonb;END IF;
 INSERT INTO accounting_period_recompute_requests(id,club_id,period_start,period_end,requested_at,last_requested_at,attempted_at,status)VALUES(gen_random_uuid(),$1,$2,$3,now(),now(),now(),'complete')ON CONFLICT(club_id,period_start,period_end)DO UPDATE SET attempted_at=now(),last_requested_at=now(),status='complete' RETURNING * INTO x;
 r:=jsonb_build_object('accounting_version',2,'club_id',$1,'period_start',$2,'period_end',$3,'status','ready','request_state','complete','request_recorded',true,'request_id',x.id,'requested_at',x.requested_at);
 UPDATE accounting_period_recompute_requests SET last_result=r WHERE id=x.id;RETURN r;END$$;
CREATE FUNCTION fn_rakeback_recompute_periods(uuid,date,date,uuid[])RETURNS jsonb LANGUAGE sql AS $$SELECT fn_rakeback_recompute_split($1,$2,$3)$$;
CREATE FUNCTION fn_union_rake_rollup_refresh_day(uuid,date)RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE FUNCTION fn_assert_cash_commission_period(uuid,uuid,timestamptz,timestamptz)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF current_setting('test.commission_bad',true)='on'THEN RAISE EXCEPTION 'original_commission_source_refused';END IF;END$$;
CREATE FUNCTION fn_weekly_accounting_deadline_check()RETURNS void LANGUAGE plpgsql AS $$BEGIN IF current_setting('test.deadline_bad',true)='on'THEN RAISE EXCEPTION 'original_deadline_refused';END IF;END$$;
-- Controlled stage contracts isolate phase order. Maintained real monetary
-- writer regressions and the actual production rollback qualify money itself.
CREATE FUNCTION fn_union_weekly_rakeback_close(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE r jsonb;BEGIN IF EXISTS(SELECT FROM phase_round1)THEN RETURN '{"success":false,"error":"already_executed"}'::jsonb;END IF;
 IF current_setting('test.fee_bad',true)='on'THEN RAISE EXCEPTION 'original_earned_fee_proof_refused';END IF;
 UPDATE phase_accounts SET balance=balance-100 WHERE kind='union_rake';UPDATE phase_accounts SET balance=balance+10 WHERE kind='union_bank';UPDATE phase_accounts SET balance=balance+90 WHERE kind='club';INSERT INTO phase_legs VALUES(1,90);INSERT INTO phase_trace(event)VALUES('round1');r:='{"success":true,"clubs_paid":1,"total_rakeback":90}'::jsonb;INSERT INTO phase_round1 VALUES(r);RETURN r;END$$;
CREATE FUNCTION phase_route(n int,uid uuid,pfrom timestamptz,pto timestamptz)RETURNS jsonb LANGUAGE plpgsql AS $$DECLARE r jsonb;BEGIN SELECT result INTO r FROM accounting_routed_settlement_runs WHERE union_id=uid AND period_start=pfrom AND period_end=pto AND round_no=n;IF FOUND THEN RETURN r||'{"duplicate":true}'::jsonb;END IF;
 IF n=2 THEN UPDATE phase_accounts SET balance=balance-40 WHERE kind='club';UPDATE phase_accounts SET balance=balance+40 WHERE kind='agent';ELSE UPDATE phase_accounts SET balance=balance-10 WHERE kind='agent';UPDATE phase_accounts SET balance=balance+10 WHERE kind='player';END IF;
 INSERT INTO phase_legs VALUES(n,CASE n WHEN 2 THEN 40 ELSE 10 END);INSERT INTO phase_trace(event)VALUES('round'||n);
 r:=jsonb_build_object('success',true,'routing_version',3,'source_version',2,'round',n,'amount',CASE n WHEN 2 THEN 40 ELSE 10 END,'payees',1,'shortfalls',0);
 INSERT INTO accounting_routed_settlement_runs VALUES(uid,'union',uid,pfrom,pto,n,r);RETURN r;END$$;
CREATE FUNCTION fn_settle_round2_club_to_agents(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT phase_route(2,$1,$2,$3)$$;
CREATE FUNCTION fn_settle_round3_agents_to_players(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT phase_route(3,$1,$2,$3)$$;
CREATE FUNCTION fn_settle_accounting_rakeback_stage(text,uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT phase_route(3,$2,$3,$4)$$;
CREATE FUNCTION fn_union_settlement_conservation_assert(uuid,timestamptz,timestamptz,jsonb,jsonb,jsonb)RETURNS void LANGUAGE plpgsql AS $$BEGIN IF(SELECT sum(balance)FROM phase_accounts)<>1100 OR(SELECT count(*)FROM phase_legs)<>3 THEN RAISE EXCEPTION 'original_conservation_refused';END IF;END$$;
CREATE FUNCTION fn_accounting_close_certificate(text,uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"ready"}'::jsonb$$;
CREATE FUNCTION fn_accounting_tournament_week_quality(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT '{"status":"ready"}'::jsonb$$;
CREATE FUNCTION fn_accounting_close_certify(text,uuid,timestamptz,timestamptz,jsonb)RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE FUNCTION fn_mark_scope_accounting_settled(text,uuid,timestamptz,timestamptz)RETURNS void LANGUAGE plpgsql AS $$BEGIN INSERT INTO phase_trace(event)VALUES('settled');END$$;
CREATE FUNCTION fn_union_pnl_qualified_clubs(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT '{"eco_commercial_terms_evidence":{"segments":[{"terms":{"eco_enabled":"true"}}]}}'::jsonb$$;
CREATE FUNCTION fn_union_eco_record(uuid,timestamptz,timestamptz,uuid)RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO phase_trace(event)VALUES('eco');RETURN '{"success":true}'::jsonb;END$$;
CREATE FUNCTION fn_union_setting(uuid,text,int)RETURNS int LANGUAGE sql AS $$SELECT 1$$;
CREATE FUNCTION fn_union_issue_weekly_invoices(uuid,timestamptz,timestamptz,boolean)RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO phase_trace(event)VALUES('invoices');INSERT INTO settlement_invoices VALUES(c(),'union_weekly_squareup',jsonb_build_object('union_id',$1,'period_start',$2,'period_end',$3),true,'paid');RETURN '{"success":true,"invoices":1}'::jsonb;END$$;
CREATE FUNCTION fn_generate_scope_credit_invoices(uuid,timestamptz,timestamptz)RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE FUNCTION fn_issue_club_weekly_accounting(uuid,timestamptz,timestamptz)RETURNS jsonb LANGUAGE sql AS $$SELECT '{"success":true}'::jsonb$$;
CREATE FUNCTION fn_union_close_post_rake_debit(jsonb)RETURNS TABLE(rw_after numeric,cb_after numeric)LANGUAGE sql AS $$SELECT 0::numeric,0::numeric$$;
